// Parse WTO timeseries API response
// WTO API returns: { Dataset: [...] } or array of data points
const rawData = $input.item.json;
const rows = [];

try {
  // Handle different WTO response formats
  let dataset = [];
  if (rawData.Dataset) {
    dataset = rawData.Dataset;
  } else if (Array.isArray(rawData)) {
    dataset = rawData;
  } else if (rawData.value) {
    dataset = rawData.value;
  }

  if (dataset.length > 0) {
    // Group by product and get latest values
    const productMap = {};
    for (const item of dataset) {
      const productName = item.ProductOrSector || item.ProductOrSectorCode || 'Agricultural Products';
      const year = item.Year || item.Period || 'unknown';
      const value = parseFloat(item.Value || item.value || 0);
      const key = productName;

      if (!productMap[key] || year > productMap[key].year) {
        productMap[key] = { year, value, productName };
      }
    }

    for (const [key, data] of Object.entries(productMap)) {
      rows.push({
        source: 'WTO',
        commodity: data.productName.substring(0, 50),
        metric: 'import_tariff',
        value: data.value,
        unit: '%',
        period: String(data.year)
      });
    }
  }
} catch (e) {
  // If WTO API returns error or unexpected format, still provide a fallback
}

// Fallback if no data parsed
if (rows.length === 0) {
  rows.push({
    source: 'WTO',
    commodity: 'Agricultural Products',
    metric: 'import_tariff',
    value: 0,
    unit: '%',
    period: '2026'
  });
}

return rows.map(r => ({ json: r }));
